import{_ as o}from"./chunks/qr_libre2direct-calib.DRaHvn-3.js";import{_ as t,o as e,c as a,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"Importare le impostazioni per Libre 2 diretto CON calibrazione","description":"","frontmatter":{"source_hash":"4954c7be6b","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/install/libre2direct-calib.md","filePath":"it/install/libre2direct-calib.md"}'),n={name:"it/install/libre2direct-calib.md"};function l(s,i,c,m,p,d){return e(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="importing-settings-for-libre-2-direct-with-calibration" tabindex="-1">Importare le impostazioni per Libre 2 diretto CON calibrazione <a class="header-anchor" href="#importing-settings-for-libre-2-direct-with-calibration" aria-label="Permalink to &quot;Importare le impostazioni per Libre 2 diretto CON calibrazione {#importing-settings-for-libre-2-direct-with-calibration}&quot;">​</a></h1><img src="'+o+'" style="zoom:60%;"><p>Scansiona il codice QR qui sotto per caricare le impostazioni necessarie per Libre 2 diretto. In Impostazioni, nel menu &quot;hamburger&quot; a sinistra, seleziona &quot;Configurazione automatica&quot; e inquadra il codice QR. Dovrai toccare il pulsante Si per confermare che vuoi importare queste impostazioni.</p><h2 id="libre-2-direct-settings-imported-from-qr-code" tabindex="-1">Impostazioni di Libre 2 diretto importate dal codice QR... <a class="header-anchor" href="#libre-2-direct-settings-imported-from-qr-code" aria-label="Permalink to &quot;Impostazioni di Libre 2 diretto importate dal codice QR... {#libre-2-direct-settings-imported-from-qr-code}&quot;">​</a></h2><p>Scansionando il codice QR otterrai le impostazioni e i valori seguenti. Sono le modifiche alle impostazioni necessarie per il corretto funzionamento di Libre 2 diretto.</p><ul><li>Dati Hardware di origine = Libre Bluetooth</li><li>Funzionalità Scansione NFC → Usa funzionalità NFC = attivato</li><li>Funzionalità Scansione NFC → Avvio della connessione bluetooth con i sensori Libre2 = Connettersi sempre ai sensori Libre 2</li><li>Funzionalità Scansione NFC → Usa il metodo più veloce di lettura multi-blocco = disattivato</li><li>Funzionalità Scansione NFC → Usa il metodo di lettura ottimizzato any-tag = disattivato</li><li>Impostazioni Meno Usate → Impostazioni avanzate per Libre 2 → Mostra i valori grezzi nel grafico = attivato</li><li>Impostazioni Meno Usate → Impostazioni avanzate per Libre 2 → Mostra informazioni sensore nello stato = attivato</li><li>Impostazioni Meno Usate → Altre opzioni → Algoritmo Libre OOP. = disattivato</li><li>Impostazioni Meno Usate → Altre opzioni → Calibrazione dell&#39;algoritmo OOP2. = Calibrate based on raw</li><li>Impostazioni Meno Usate → Altre opzioni → Liscia dati Libre. = attivato</li><li>Impostazioni Meno Usate → Altre opzioni → Recupera cronologia Libre = attivato</li><li>Impostazioni Meno Usate → Impostazioni Bluetooth → Attiva Bluetooth = attivato</li><li>Impostazioni Meno Usate → Impostazioni Bluetooth → Consenti unbonding Blucon = attivato</li><li>Impostazioni Meno Usate → Impostazioni Bluetooth → Watchdog Bluetooth = attivato</li><li>Impostazioni Meno Usate → Impostazioni Bluetooth → Trust Auto-Connect = attivato</li><li>Impostazioni Meno Usate → Impostazioni Bluetooth → Usa Scansione In Background = attivato</li><li>Impostazioni Meno Usate → Impostazioni Bluetooth → Chiusura GATT per scollegamento BLE = disattivato</li></ul>',6)])])}const h=t(n,[["render",l]]);export{b as __pageData,h as default};
